#include <bits/stdc++.h>
using namespace std;
using vi = vector<int>;
using vpii = vector<pair<int, int>>;
using pii = pair<int, int>;
using ll = long long;
using pll = pair<ll, ll>;
using pdd = pair<double, double>;
using vll = vector<ll>;
constexpr int INF = 0x3f3f3f3f;
constexpr ll MOD = 1000000007LL;
constexpr ll INV = 570000004LL;
constexpr double EPSILON = 0.00001;
constexpr int MN = 22;

int n;
ll p[MN][MN];
vi permsA[MN];
vi permsB[MN];
ll bmA[1<<MN];
ll bmB[1<<MN];
ll f[1<<MN];

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t = 0;
    int aah[6] = {0, 1, 2, 3, 4, 5};
    do{
        if(aah[0] < aah[1] && aah[1] < aah[2] && aah[3] < aah[4] && aah[4] < aah[5]){
            permsA[t] = {aah[0], aah[1], aah[2]};
            permsB[t] = {aah[3], aah[4], aah[5]};
            ++t;
        }
    } while(next_permutation(aah, aah+6));

    cin >> n;
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < n; ++j){
            cin >> p[i][j];
            p[i][j] = (p[i][j]*INV)%MOD;
        }
    }
    for(int i = 0; i < 6; ++i){
        for(int j = n; j < 6; ++j){
            if(i == j) p[i][j] = 1;
            else{p[i][j] = 0; p[j][i] = 0;}
        }
    }
    n = 6;

    for(int i = 0; i < (1<<18); ++i){
        ll prob1 = 1;
        ll prob2 = 1;
        int bm1 = 0;
        int bm2 = 0;
        for(int j = 0; j < 6; ++j){
            for(int k = 0; k < 3; ++k){
                int res = j*3+k;
                if((1<<res) & i){
                    prob1 *= p[j][k];
                    prob2 *= p[j][k+3];
                } else{
                    prob1 *= (1+MOD-p[j][k]);
                    prob2 *= (1+MOD-p[j][k+3]);
                }
                prob1 %= MOD;
                prob2 %= MOD;
            }
        }
        for(int ot = 0; ot < 20; ++ot){
            int ord[3] = {0, 1, 2};
            bool ok = false;
            do{
                bool ok2 = true;
                for(int j = 0; j < 3; ++j){
                    int val = permsA[ot][ord[j]];
                    int loc = val*3+j;
                    if(!((1<<loc)&i)){
                        ok2 = false;
                        break;
                    }
                }
                if(ok2){
                    ok = true;
                    break;
                }
            } while(next_permutation(ord, ord+3));
            if(ok){
                bm1 ^= (1<<ot);
            }
        }
        for(int ot = 0; ot < 20; ++ot){
            int ord[3] = {0, 1, 2};
            bool ok = false;
            do{
                bool ok2 = true;
                for(int j = 0; j < 3; ++j){
                    int val = permsB[ot][ord[j]];
                    int loc = val*3+j;
                    if(!((1<<loc)&i)){
                        ok2 = false;
                        break;
                    }
                }
                if(ok2){
                    ok = true;
                    break;
                }
            } while(next_permutation(ord, ord+3));
            if(ok){
                bm2 ^= (1<<ot);
            }
        }
        bmA[bm1] = (bmA[bm1]+prob1)%MOD;
        bmB[bm2] = (bmB[bm2]+prob2)%MOD;
    }
    for(int i = 0; i < (1<<20); ++i){
        f[i] = bmA[i];
    }
    for(int i = 0; i < 20; ++i){
        for(int mask = 0; mask < (1<<20); ++mask){
            if(mask & (1<<i)){
                f[mask] += f[mask ^ (1<<i)];
                f[mask] %= MOD;
            }
        }
    }
    ll sm = 0;
    for(int i = 0; i < (1<<20); ++i){
        int o = (1<<20)-1;
        sm += (bmB[i]*f[o^i]);
        sm %= MOD;
    }
    cout << (1+MOD-sm)%MOD << "\n";

    return 0;
}
